// The adage mod's registration (plan B1–B4, C3–C9, D5; docs/claude-mod/impl/mod-structure.md).
//
// `claude plugin validate` follows `$` only into functions declared in this file and refuses `$`,
// or any noun of it, passed across an import; it reads a state reference only as literals in a
// const of this file, and an environment variable only by a literal name. So this file holds the
// three things that need `$` and nothing else: the state table's atoms, `mod($, options)` (every
// call the mod makes, as a closure over `$`), and the `on(...)` lines, one per hook in a fixed
// order (registrations nest first outermost, so the order is behaviour), each delegating to the
// module that does the work. Everything else is in modules that take a `Mod` and never see `$`.
import { atom, read, update } from 'claude-code'
import type { EngineInterface, ProcessSpawnRequest, Register } from 'claude-code'

import * as actions from './actions'
import * as attach from './attach'
import { guard, guardSpawn } from './bridge'
import * as call from './call'
import * as commands from './commands'
import * as dialog from './dialog'
import type { Els } from './draw/els'
import * as sites from './draw/sites'
import * as ledger from './ledger'
import type { Mod, Options } from './mod'
import { runtime } from './mod'
import * as observe from './observe'
import { STATE0 } from './plugin'
import { guardPress } from './press'
import * as session from './session'
import * as skill from './skill'
import * as step from './step'

// The state table (plugin.ts `STATE0`, types/index.d.ts): one atom per `$.state` key.
const FIRED = atom({ plugin: 'adage', key: 'fired' } as const, STATE0.fired)
const PREDICTED = atom({ plugin: 'adage', key: 'predicted' } as const, STATE0.predicted)
const MARKS = atom({ plugin: 'adage', key: 'marks' } as const, STATE0.marks)
const BATCHES = atom({ plugin: 'adage', key: 'batches' } as const, STATE0.batches)
const FEED = atom({ plugin: 'adage', key: 'feed' } as const, STATE0.feed)
const ROWS = atom({ plugin: 'adage', key: 'rows' } as const, STATE0.rows)
const TICKS = atom({ plugin: 'adage', key: 'ticks' } as const, STATE0.ticks)
const HEALTH = atom({ plugin: 'adage', key: 'health' } as const, STATE0.health)
const LEARNER = atom({ plugin: 'adage', key: 'learner' } as const, STATE0.learner)
const REFLEXES = atom({ plugin: 'adage', key: 'reflexes' } as const, STATE0.reflexes)
const CHECKS = atom({ plugin: 'adage', key: 'checks' } as const, STATE0.checks)
const LAPSED = atom({ plugin: 'adage', key: 'lapsed' } as const, STATE0.lapsed)
const PACKS = atom({ plugin: 'adage', key: 'packs' } as const, STATE0.packs)
const MODE = atom({ plugin: 'adage', key: 'mode' } as const, STATE0.mode)
const VIEW = atom({ plugin: 'adage', key: 'view' } as const, STATE0.view)
const MAP = atom({ plugin: 'adage', key: 'map' } as const, STATE0.map)
const TURN = atom({ plugin: 'adage', key: 'turn' } as const, STATE0.turn)
const PRESS = atom({ plugin: 'adage', key: 'press' } as const, STATE0.press)
const ASKED = atom({ plugin: 'adage', key: 'asked' } as const, STATE0.asked)
const ALLOW = atom({ plugin: 'adage', key: 'allow' } as const, STATE0.allow)
const SKILLS = atom({ plugin: 'adage', key: 'skills' } as const, STATE0.skills)
const CANDIDATES = atom({ plugin: 'adage', key: 'candidates' } as const, STATE0.candidates)
const DAG = atom({ plugin: 'adage', key: 'dag' } as const, STATE0.dag)

/** What one load of the module keeps between hooks (mod.ts `Runtime`). */
const rt = runtime()

/** The capabilities over this `$`, the runtime and the options: what every hook function is handed. */
function mod($: EngineInterface, options: Options): Mod {
  return {
    rt,
    options,
    state: {
      fired: { read: () => read($, FIRED), update: f => update($, FIRED, f) },
      predicted: { read: () => read($, PREDICTED), update: f => update($, PREDICTED, f) },
      marks: { read: () => read($, MARKS), update: f => update($, MARKS, f) },
      batches: { read: () => read($, BATCHES), update: f => update($, BATCHES, f) },
      feed: { read: () => read($, FEED), update: f => update($, FEED, f) },
      rows: { read: () => read($, ROWS), update: f => update($, ROWS, f) },
      ticks: { read: () => read($, TICKS), update: f => update($, TICKS, f) },
      health: { read: () => read($, HEALTH), update: f => update($, HEALTH, f) },
      learner: { read: () => read($, LEARNER), update: f => update($, LEARNER, f) },
      reflexes: { read: () => read($, REFLEXES), update: f => update($, REFLEXES, f) },
      checks: { read: () => read($, CHECKS), update: f => update($, CHECKS, f) },
      lapsed: { read: () => read($, LAPSED), update: f => update($, LAPSED, f) },
      packs: { read: () => read($, PACKS), update: f => update($, PACKS, f) },
      mode: { read: () => read($, MODE), update: f => update($, MODE, f) },
      view: { read: () => read($, VIEW), update: f => update($, VIEW, f) },
      map: { read: () => read($, MAP), update: f => update($, MAP, f) },
      turn: { read: () => read($, TURN), update: f => update($, TURN, f) },
      press: { read: () => read($, PRESS), update: f => update($, PRESS, f) },
      asked: { read: () => read($, ASKED), update: f => update($, ASKED, f) },
      allow: { read: () => read($, ALLOW), update: f => update($, ALLOW, f) },
      skills: { read: () => read($, SKILLS), update: f => update($, SKILLS, f) },
      candidates: { read: () => read($, CANDIDATES), update: f => update($, CANDIDATES, f) },
      dag: { read: () => read($, DAG), update: f => update($, DAG, f) },
    },
    // The store table (plugin.ts `STORE_KEYS`): one cell per `$.store` key.
    store: {
      tab: { get: () => $.store.get('adage.tab'), set: v => $.store.set('adage.tab', v) },
      harness: { get: () => $.store.get('adage.harness'), set: v => $.store.set('adage.harness', v) },
      asked: { get: () => $.store.get('adage.asked'), set: v => $.store.set('adage.asked', v) },
      kept: { get: () => $.store.get('adage.kept'), set: v => $.store.set('adage.kept', v) },
      latest: { get: () => $.store.get('adage.latest'), set: v => $.store.set('adage.latest', v) },
    },
    // The only ways to a process, each behind its allow-list and CLAUDECODE=1.
    run: guard((argv, init) => $.process.run(argv, init)),
    spawn: guardSpawn((request: ProcessSpawnRequest) => $.process.spawn(request)),
    pressRun: guardPress((argv, init) => $.process.run(argv, init)),
    env: {
      pluginData: () => $.env.get('CLAUDE_PLUGIN_DATA'),
      configDir: () => $.env.get('CLAUDE_CONFIG_DIR'),
      home: () => $.env.get('HOME'),
      userProfile: () => $.env.get('USERPROFILE'),
      observe: () => $.env.get('ADAGE_MOD_OBSERVE'),
      ascii: () => $.env.get('ADAGE_ASCII'),
      reducedMotion: () => $.env.get('ADAGE_REDUCED_MOTION'),
      os: () => $.env.get('OS'),
    },
    plugin: { root: () => $.plugin.root, name: () => $.plugin.name },
    fs: { read: path => $.fs.read(path), exists: path => $.fs.exists(path) },
    command: { register: c => $.command.register(c), list: () => $.command.list() },
    session: { id: () => $.session.id(), cwd: () => $.session.cwd(), repo: () => $.session.repo(), usage: a => $.session.usage(a), version: () => $.session.version() },
    clock: { now: () => $.clock.now(), every: (ms, fn) => $.clock.every(ms, fn), after: (ms, fn) => $.clock.after(ms, fn) },
    checkBash: async command => (await $.tool.check({ tool: 'Bash', input: { command } })).decision,
    checkTool: (tool, input) => $.tool.check({ tool, input }),
    ui: {
      status: text => $.ui.status(text),
      toast: text => $.ui.toast(text),
      notice: (id, text) => $.ui.notice(id, text),
      open: pane => $.ui.open(pane),
      close: pane => $.ui.close(pane),
      ask: (question, answers) => $.ui.ask(question, answers),
      copy: args => $.ui.copy(args),
      scroll: args => $.ui.scroll(args),
      invalidate: () => $.ui.invalidate('ui.render'),
      resolve: e => $.ui.resolve(e) as Els,
    },
  }
}

export const register: Register = (on, options) => {
  on('session.start', async ($, e, next) => session.onStart(mod($, options), e, next))
  on('classic.SessionStart', async ($, e, next) => session.onShimStart(mod($, options), e, next))
  on('classic.UserPromptSubmit', async ($, e, next) => observe.onPrompt(mod($, options), e, next))
  on('classic.PostToolBatch', async ($, e, next) => observe.onToolBatch(mod($, options), e, next))
  on('classic.PostToolUseFailure', async ($, e, next) => observe.onToolFailure(mod($, options), e, next))
  on('classic.Stop', async ($, e, next) => observe.onStop(mod($, options), e, next))
  on('classic.PreToolUse', async ($, e, next) => observe.onPreToolUse(mod($, options), e, next))
  on('turn.step', async function* ($, e, next) { return yield* step.onStep(mod($, options), e, next) })
  on('turn.complete', async ($, e, next) => ledger.onTurnEnd(mod($, options), e, next))
  on('tool.call', { tool: 'Bash' }, async ($, e, next) => call.onBashCall(mod($, options), e, next))
  on('tool.call', async ($, e, next) => call.onPredictedCall(mod($, options), e, next))
  on('prompt.compose', async ($, e, next) => attach.onCompose(mod($, options), e, next))
  on('tool.describe', { tool: 'Bash' }, async ($, e, next) => attach.onDescribe(mod($, options), e, next))
  on('session.compact', async ($, e, next) => attach.onCompact(mod($, options), e, next))
  on('agent.spawn', async ($, e, next) => attach.onSpawn(mod($, options), e, next))
  on('command.run', { command: 'adage' }, async ($, e) => commands.onCommand(mod($, options), e))
  on('ui.render', { component: 'InfoNotice' }, async ($, e, next) => sites.onInfoNotice(mod($, options), e, next))
  on('ui.render', { component: 'UserMessage' }, async ($, e, next) => sites.onUserMessage(mod($, options), e, next))
  on('ui.render', { component: 'ToolUse' }, async ($, e, next) => sites.onToolUse(mod($, options), e, next))
  on('ui.render', { component: 'ToolResult' }, async ($, e, next) => sites.onToolResult(mod($, options), e, next))
  on('ui.render', { component: 'Spinner' }, async ($, e, next) => sites.onSpinner(mod($, options), e, next))
  on('ui.render', { component: 'TurnDuration' }, async ($, e, next) => sites.onTurnDuration(mod($, options), e, next))
  if (options.band !== false) on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => sites.onAbovePrompt(mod($, options), e, next))
  on('ui.render', { component: 'Pane', requestId: 'adage' }, async ($, e, next) => sites.onPane(mod($, options), e, next))
  on('ui.render', { component: 'Pane', requestId: 'adage-inspect' }, async ($, e, next) => sites.onInspectPane(mod($, options), e, next))
  on('ui.render', { component: 'CommandOutput', props: { command: 'adage' } }, async ($, e, next) => sites.onCommandOutput(mod($, options), e, next))
  on('session.start', { isInteractive: [true, false] }, async ($, e, next) => dialog.onStart(mod($, options), e, next))
  on('classic.SessionStart', { hook_event_name: 'SessionStart' }, async ($, e, next) => dialog.onShimStart(mod($, options), e, next))
  on('turn.complete', { reason: 'answer' }, async ($, e, next) => dialog.onTurnEnd(mod($, options), e, next))
  on('skill.prompt', async ($, e, next) => skill.onSkillPrompt(mod($, options), e, next))
  on('ui.render', { component: 'ToolGroup' }, async ($, e, next) => sites.onToolGroup(mod($, options), e, next))
  on('ui.render', { component: 'ToolUse', props: { tool: 'Skill' } }, async ($, e, next) => sites.onSkillToolUse(mod($, options), e, next))
  on('ui.render', { component: 'Pane', requestId: 'adage-allow' }, async ($, e, next) => sites.onAllowPane(mod($, options), e, next))
  on('ui.open', { id: 'adage' }, async ($, e, next) => actions.onPaneOpen(mod($, options), e, next))
  on('ui.close', { id: 'adage' }, async ($, e, next) => actions.onPaneClose(mod($, options), e, next))
}

files.hooks/actions.ts:
// What the person's presses in the pane do, and opening it (docs/claude-mod/ux-design.md §6): the
// tabs, the filters, the inspect pane, the pause, copying a command, the Health tab's one action
// (`adage condition`) and `Explore in browser` (`adage map`, started once). None of these is a
// decision: a decision is a press (dialog.ts, token.ts), which draw/sites.ts adds to these.
import { say } from './bridge'
import type { PaneActions } from './draw/pane'
import { togglePause } from './follower'
import type { AnswerAt, EventAt, Mod, NextAt } from './mod'
import { quietly } from './mod'
import type { View } from './plugin'
import { INSPECT, MAP0, PANE } from './plugin'
import { mapUrl } from './reads'
import { refresh } from './refresh'
import { visibleRows } from './view/pane'

/** Opens the pane on a tab, focused: the person asked (`/adage …`, ux-design §6). */
export async function openPane(m: Mod, tab: View['tab']): Promise<void> {
  await m.state.view.update(v => ({ ...v, tab }))
  await m.ui.open({ id: PANE, title: 'adage', focus: true, closeOnEscape: true, holdToasts: true, rows: 20 })
  if (tab !== 'live') quietly(refresh(m, true))
}

/** `why`: the pane, focused, on that reflex (or pack), with `e enable` and `n not this one`. */
export async function showReflex(m: Mod, key: string): Promise<void> {
  await m.state.view.update(v => ({ ...v, tab: 'reflexes' as const, expanded: key, rfilter: '', strength: 'all', lifecycle: 'all' }))
  await openPane(m, 'reflexes')
}

/** Copies a command for the person and says so (`toast.copied`, `toast.copy.unavailable`). */
export async function copy(m: Mod, command: string, on?: string): Promise<boolean> {
  const target = on === 'terminal' || on === 'desktop' || on === 'vscode' || on === 'mobile' ? on : undefined
  const done = await m.ui.copy(target === undefined ? { text: command } : { text: command, surface: target }).catch(() => ({ isCopied: false as const }))
  m.ui.toast(done.isCopied ? `copied: ${command}` : 'copy is not available here · the command is in /adage health')
  return done.isCopied
}

/** `Explore in browser` (ux-design §6): starts `adage map` once (it opens the browser) and keeps its address. */
export async function explore(m: Mod): Promise<string | undefined> {
  const now = await m.state.map.read()
  if (now.url !== '') return now.url
  if (m.rt.cli === undefined || now.starting) return undefined
  await m.state.map.update(x => ({ ...x, starting: true }))
  const stream = m.spawn({ argv: [m.rt.cli, 'map', '--port', '0'], cwd: await m.session.cwd() })
  return new Promise<string | undefined>(resolve => {
    let said = ''
    let found = false
    quietly((async () => {
      try {
        for await (const chunk of stream) {
          said = (said + chunk.text).slice(-4096)
          const url = found ? undefined : mapUrl(said)
          if (url !== undefined) {
            found = true
            await m.state.map.update(() => ({ url, starting: false }))
            resolve(url)
          }
        }
      } catch {
        // It could not start, or it ended: the link goes, and a press starts it again.
      }
      if (!found) resolve(undefined)
      await m.state.map.update(() => MAP0)
    })())
  })
}

/** The pane's handlers (draw/pane.tsx calls them from presses, picks and fields); the presses are added by draw/sites.ts. */
export function paneActions(m: Mod): Omit<PaneActions, 'press'> {
  return {
    tab: tab => {
      quietly(m.state.view.update(v => ({ ...v, tab })))
      quietly(m.store.tab.set(tab))
    },
    filter: (value, submit) => quietly(m.state.view.update(v => ({ ...v, filter: submit && value.trim() === '' ? '' : value }))),
    inspect: seq => {
      quietly((async () => {
        const view = await m.state.view.read()
        const rows = await m.state.rows.read()
        const ascii = (await m.state.mode.read()).ascii
        // A row the filter removed is never inspected (ux-design §6.1).
        if (!visibleRows(rows, view.filter, view.hideQuiet, ascii).some(r => r.seq === seq)) return
        await m.state.view.update(v => ({ ...v, selected: seq }))
        await m.ui.open({ id: INSPECT, title: 'adage · inspect', focus: true, closeOnEscape: true, rows: 12 })
      })())
    },
    pause: () => quietly(togglePause(m)),
    quiet: () => quietly(m.state.view.update(v => ({ ...v, hideQuiet: !v.hideQuiet }))),
    newest: () => quietly(m.ui.scroll({ in: PANE, to: 'start' })),
    rfilter: value => quietly(m.state.view.update(v => ({ ...v, rfilter: value }))),
    pick: (which, value) => quietly(m.state.view.update(v => (which === 'strength' ? { ...v, strength: value } : { ...v, lifecycle: value }))),
    expand: key => quietly(m.state.view.update(v => ({ ...v, expanded: v.expanded === key ? '' : key }))),
    copy: (command, on) => quietly(copy(m, command, on)),
    condition: () => {
      quietly((async () => {
        await say(m.run, m.rt.cli, ['condition'], await m.session.cwd())
        await refresh(m, true)
      })())
    },
    explore: () => quietly(explore(m)),
    history: () => quietly(m.state.view.update(v => ({ ...v, history: !v.history }))),
  }
}

/** Whether the pane is open: the band's `1 pattern noticed` cell shows only while it is closed. */
export async function onPaneOpen(m: Mod, e: EventAt<'ui.open', { id: 'adage' }>, next: NextAt<'ui.open', { id: 'adage' }>): AnswerAt<'ui.open', { id: 'adage' }> {
  m.rt.paneOpen = true
  return next(e)
}

export async function onPaneClose(m: Mod, e: EventAt<'ui.close', { id: 'adage' }>, next: NextAt<'ui.close', { id: 'adage' }>): AnswerAt<'ui.close', { id: 'adage' }> {
  m.rt.paneOpen = false
  return next(e)
}

files.hooks/attach.ts:
// Pure: where Adage's standing text is attached (docs/claude-mod/architecture.md §1b.3, §3.6–§3.8;
// plan C5, C9). The binary answers `Standing` once per session (`{ standing, environment, compact,
// conventions }`, and `subagent` when asked about a subagent); the mod places each part where the
// engine keeps it: the procedures as a `session` section of the system prompt (cached for the
// session), the environment note and the learned lookup conventions in the Bash tool's
// description, the compaction instruction at compaction, and a subagent's text before its prompt. Every part is the binary's words; an empty part attaches
// nothing, and a failed ask is an empty answer. The answer is asked once per session id and kept
// in the runtime, so every request of the session reads the same text (the prompt cache keeps it).
import type { PromptComposeSection } from 'claude-code'

import { askBinary } from './binary'
import type { AnswerAt, EventAt, Mod, NextAt } from './mod'
import { isRecord, str } from './shape'

/** The session's answer, kept for the session: the same text at every request (the cache holds it). */
export type Standing = { standing: string; environment: string; compact: string; conventions: string }

const NO_STANDING: Standing = { standing: '', environment: '', compact: '', conventions: '' }

/** The binary's `Standing` payload (C5, C9), exactly. */
type StandingPayload = {
  session_id: string
  cwd: string
  hook_event_name: 'Standing'
  via: 'mod'
  /** Observe mode: the binary answers as for the control arm (only `compact`). */
  observe?: true
  /** A subagent about to start (`agent.spawn`): what it is and what it is asked. */
  agent?: { type: string; description: string; prompt: string }
  /**
   * The session's ask: the binary adds `conventions`, one sentence per learned lookup convention
   * (O0-fixes-notes.md §6); without it the answer is as before.
   */
  conventions?: true
}

/** `Standing` is read-only and asked off the hot path (once a session, once a spawn). */
const STANDING_TIMEOUT_MS = 2000

/** The section's id: a plugin's own is `<plugin>:<name>` (the engine's rule). */
export const SECTION_ID = 'adage:procedures'

/** The answer's four session parts; anything missing or malformed is empty. */
export function standingOf(answer: unknown): Standing {
  if (!isRecord(answer)) return NO_STANDING
  return { standing: str(answer.standing), environment: str(answer.environment), compact: str(answer.compact), conventions: str(answer.conventions) }
}

/** What the Bash tool's description carries: the environment note, then the lookup conventions. */
export const describedNote = (s: Standing): string => [s.environment, s.conventions].filter(t => t !== '').join('\n\n')

/** What a subagent is told before it starts (the answer's `subagent`), or empty. */
export const subagentOf = (answer: unknown): string => (isRecord(answer) ? str(answer.subagent) : '')

/**
 * The system prompt's sections with the procedures appended as one `session` section (after every
 * `shared` one, as the engine requires), or unchanged when there is none. A section of the same id
 * already in the list is replaced, never doubled.
 */
export function withSection(sections: readonly PromptComposeSection[], standing: string): readonly PromptComposeSection[] {
  if (standing === '') return sections
  return [...sections.filter(s => s.id !== SECTION_ID), { id: SECTION_ID, text: standing, scope: 'session' }]
}

/** The Bash tool's description with the environment note after it, once; unchanged without one. */
export function withNote(description: string, note: string): string {
  if (note === '' || description.includes(note)) return description
  return description === '' ? note : `${description}\n\n${note}`
}

/** What compaction is told to keep: the person's own words first, then Adage's line, once. */
export function withInstruction(instructions: string | undefined, compact: string): string | undefined {
  if (compact === '' || (instructions ?? '').includes(compact)) return instructions
  return [instructions, compact].filter((s): s is string => s !== undefined && s !== '').join('\n')
}

/** A subagent's prompt with what it is told before it: the marked blocks, then its task. */
export const withPreamble = (prompt: string, subagent: string): string => (subagent === '' ? prompt : `${subagent}\n\n${prompt}`)

/**
 * Whether a transcript row is an attachment Adage's plugin made, by structure: the row's own
 * `origin` names this plugin. Never by its text (a row quoting `<adage-reflex` is the person's or
 * the model's own). Claude Code 2.1.288's rows carry no origin, so nothing is removed there (Q5).
 */
export function isAdageAttachment(message: unknown): boolean {
  if (!isRecord(message) || !isRecord(message.origin)) return false
  const o = message.origin
  return o.kind === 'plugin' && o.plugin === 'adage'
}

/** The messages compaction runs over, without Adage's own attachment rows when they are addressable. */
export function withoutAttachments<M>(messages: readonly M[]): readonly M[] {
  return messages.some(isAdageAttachment) ? messages.filter(m => !isAdageAttachment(m)) : messages
}

/** The `Standing` payload for this session, and for a subagent about to start. */
async function standingPayload(m: Mod, agent?: StandingPayload['agent']): Promise<StandingPayload> {
  return {
    session_id: await m.session.id(),
    cwd: await m.session.cwd(),
    hook_event_name: 'Standing',
    via: 'mod',
    ...(m.rt.observing ? { observe: true as const } : {}),
    ...(agent === undefined ? { conventions: true as const } : { agent }),
  }
}

/**
 * The session's standing text, asked once per session id; nothing while the mod is inert (the
 * question waits for a binary, so a first session whose link the shim makes later still asks).
 */
export async function standing(m: Mod): Promise<Standing> {
  if (m.rt.bin === undefined) return NO_STANDING
  const session = await m.session.id()
  if (m.rt.standingFor?.session !== session) {
    const answer = standingPayload(m)
      .then(p => askBinary(m, 'Standing', p, STANDING_TIMEOUT_MS))
      .then(a => (a.ok ? standingOf(a.answer) : NO_STANDING), () => NO_STANDING)
    m.rt.standingFor = { session, answer }
  }
  return m.rt.standingFor.answer
}

/** Standing text once, from the cache (§3.6, C5): the procedures as one `session` section of the system prompt. */
export async function onCompose(m: Mod, e: EventAt<'prompt.compose'>, next: NextAt<'prompt.compose'>): AnswerAt<'prompt.compose'> {
  const composed = await next(e)
  if (m.rt.bin === undefined) return composed
  const text = (await standing(m).catch(() => NO_STANDING)).standing
  return text === '' ? composed : { ...composed, sections: withSection(composed.sections, text) }
}

/**
 * The Bash tool's description carries the environment note and the lookup conventions once
 * (§1b.3, C9): how Python and the tests run here, and how work items are looked up, where the tool
 * is described rather than at each call.
 */
export async function onDescribe(m: Mod, e: EventAt<'tool.describe', { tool: 'Bash' }>, next: NextAt<'tool.describe', { tool: 'Bash' }>): AnswerAt<'tool.describe', { tool: 'Bash' }> {
  const described = await next(e)
  if (m.rt.bin === undefined) return described
  const note = describedNote(await standing(m).catch(() => NO_STANDING))
  const description = withNote(described.description, note)
  return description === described.description ? described : { ...described, description }
}

/**
 * Compaction keeps what the session followed (§3.7, C5): the binary's instruction, in both arms;
 * Adage's own attachment rows go only where the engine marks them as the plugin's.
 */
export async function onCompact(m: Mod, e: EventAt<'session.compact'>, next: NextAt<'session.compact'>): AnswerAt<'session.compact'> {
  if (m.rt.bin === undefined) return next(e)
  const compact = (await standing(m).catch(() => NO_STANDING)).compact
  const instructions = withInstruction(typeof e.instructions === 'string' ? e.instructions : undefined, compact)
  // A transcript that is not a list (a host that hands none) is passed on as it came.
  const messages = Array.isArray(e.messages) ? withoutAttachments(e.messages) : e.messages
  if (instructions === e.instructions && messages === e.messages) return next(e)
  return next({ ...e, messages, ...(instructions === undefined ? {} : { instructions }) })
}

/**
 * A subagent is told the conventions its task binds before its first request (§3.8, C9). A fork
 * carries the session's own context already, and is left as it is.
 */
export async function onSpawn(m: Mod, e: EventAt<'agent.spawn'>, next: NextAt<'agent.spawn'>): AnswerAt<'agent.spawn'> {
  if (m.rt.bin === undefined || e.fork) return next(e)
  let told = ''
  try {
    // The session's own answer first: the binary keeps the session's standing text from it.
    await standing(m)
    const asked = await askBinary(m, 'Standing', await standingPayload(m, { type: e.subagentType, description: e.description, prompt: e.prompt }), STANDING_TIMEOUT_MS)
    told = asked.ok ? subagentOf(asked.answer) : ''
  } catch {
    // Told nothing: the subagent starts as the model asked.
  }
  return told === '' ? next(e) : next({ ...e, prompt: withPreamble(e.prompt, told) })
}

files.hooks/bridge.ts:
// The one way the mod reaches the binary (docs/claude-mod/architecture.md §2 rule 1): every
// decision is `<bin> hook claude <Event>` with the payload on stdin; the answer is tagged so a
// failure is never mistaken for "nothing to say", and every failure is `{ ok: false }` (fail open,
// §6 invariant 2). What the mod draws it reads from `adage` itself, by a short list of exact
// argument vectors, every one read-only or a turn-down (`off`).
//
// No `$` crosses into this file (`claude plugin validate` follows `$` only within one file, and
// refuses a module that passes it across an import). register.ts hands `guard` and `guardSpawn`
// the functions that call `$.process.run` and `$.process.spawn`; both enforce the argv allow-list
// and set CLAUDECODE=1 on the child (F11: every child the mod runs is an agent session's), so every
// child below goes through them. The person-only verbs are not here: they run only through the
// press (plan B4), never from a hook, a feed line or a command.
import type { HookStream, ProcessRunInit, ProcessRunResult, ProcessSpawnChunk, ProcessSpawnRequest, ProcessSpawnResult } from 'claude-code'

import { BIN, CLI } from './plugin'

/**
 * The verbs this module may run, by their head (`argv[1]`; the status card's `--json` reads as
 * `status`). `isAllowed` holds each to its exact shape; `scripts/check-plugin.mjs` holds this
 * literal to architecture §2's list, plus `condition` (the Health tab's one action, ux-design §6.3)
 * and `delegate` (only `delegate status --json`: the lapsed grants the band and Health list).
 */
export const ALLOWED_VERBS: readonly string[] = ['hook', 'version', 'watch', 'graph', 'doctor', 'status', 'ledger', 'off', 'map', 'condition', 'delegate']

/** `$.process.run`, as register.ts hands it over. */
export type Run = (argv: readonly string[], init?: ProcessRunInit) => Promise<ProcessRunResult>

/** `$.process.spawn`, as register.ts hands it over. */
export type Spawn = (request: ProcessSpawnRequest) => HookStream<ProcessSpawnChunk, ProcessSpawnResult>

/** What a hook event's answer may carry; the binary owns the shape, the mod reads `predict`. */
type HookAnswer = { [key: string]: unknown }

export type Asked = { ok: true; answer: HookAnswer | undefined } | { ok: false }

/** A `--json` read: the object the verb printed, or a failure. */
export type Read = { ok: true; json: HookAnswer } | { ok: false }

const isExact = (argv: readonly string[], tail: readonly string[]): boolean =>
  argv.length === tail.length + 1 && tail.every((t, i) => argv[i + 1] === t)

/** The head of an argv as T-X-04 counts it: the status card (`--json --for-session`) is `status`. */
export function headOf(argv: readonly string[]): string {
  const verb = argv[1] ?? ''
  if (verb === '--json') return 'status'
  if (verb === 'ledger') return `ledger ${argv[2] ?? ''}`.trim()
  return verb
}

/**
 * Whether `argv` (binary first) is one the mod may run, each verb in its one exact shape:
 * `version`; `hook claude <Event>` (an event name of letters only); `watch --follow --json --stdin
 * ignore --repo <dir> --session <id> [--since <cursor>]`; `graph --json`; `doctor --json`; `status --json`;
 * `--json --for-session` (the status card); `ledger note`; `off`; `map --port 0`; `condition`;
 * `delegate status --json`.
 */
export function isAllowed(argv: readonly string[]): boolean {
  const verb = argv[1]
  if (verb === undefined) return false
  if (verb === '--json') return isExact(argv, ['--json', '--for-session'])
  if (!ALLOWED_VERBS.includes(verb)) return false
  switch (verb) {
    case 'version':
    case 'off':
    case 'condition':
      return argv.length === 2
    case 'hook':
      return argv.length === 4 && argv[2] === 'claude' && /^[A-Za-z]+$/.test(argv[3] ?? '')
    case 'graph':
    case 'doctor':
    case 'status':
      return isExact(argv, [verb, '--json'])
    case 'ledger':
      return isExact(argv, ['ledger', 'note'])
    case 'map':
      return isExact(argv, ['map', '--port', '0'])
    case 'delegate':
      return isExact(argv, ['delegate', 'status', '--json'])
    case 'watch': {
      const fixed = ['watch', '--follow', '--json', '--stdin', 'ignore', '--repo']
      if (!fixed.every((t, i) => argv[i + 1] === t)) return false
      const repo = argv[7] ?? ''
      const session = argv[9] ?? ''
      if (repo === '' || argv[8] !== '--session' || session === '' || session.startsWith('-')) return false
      if (argv.length === 10) return true
      return argv.length === 12 && argv[10] === '--since' && (argv[11] ?? '') !== ''
    }
    default:
      return false
  }
}

/**
 * The guarded runner: an argv off the allow-list is refused before any process starts, and the
 * child's environment always carries CLAUDECODE=1, whatever the caller passed.
 */
export function guard(run: Run): Run {
  return (argv, init = {}) => {
    if (!isAllowed(argv)) return Promise.reject(new Error(`adage bridge: argv not allowed: ${argv.slice(1).join(' ')}`))
    return run(argv, { ...init, env: { ...init.env, CLAUDECODE: '1' } })
  }
}

/** The guarded spawner: the same allow-list and CLAUDECODE=1 for a child the mod follows. */
export function guardSpawn(spawn: Spawn): Spawn {
  return request => {
    if (!isAllowed(request.argv)) throw new Error(`adage bridge: argv not allowed: ${request.argv.slice(1).join(' ')}`)
    return spawn({ ...request, env: { ...request.env, CLAUDECODE: '1' } })
  }
}

/**
 * The separator a path is spelled with: a backslash for a Windows path spelled with them (a drive,
 * `C:\Users\me`, or a share), `/` for every other (a Unix path, or Windows spelled with `/`).
 */
export const sepOf = (p: string): string => (/^(?:[A-Za-z]:\\|\\\\)/.test(p) ? '\\' : '/')

/** `base` and `parts` joined with base's own separator, base's trailing separators dropped. */
export function joinPath(base: string, ...parts: string[]): string {
  return [base.replace(/[\\/]+$/, ''), ...parts].join(sepOf(base))
}

/** A data directory's name for a plugin's key (`<plugin>@<source>`): every character but [A-Za-z0-9_-] as `-`. */
const dataName = (key: string): string => key.replace(/[^a-zA-Z0-9\-_]/g, '-')

/**
 * The plugin's data directory derived from its root, as Claude Code lays them out for an installed
 * plugin: root `<config>/plugins/cache/<marketplace>/<plugin>/<version>`, data
 * `<config>/plugins/data/<plugin@marketplace, non [A-Za-z0-9_-] as '-'>`, either separator.
 * Undefined for any other root (a --plugin-dir checkout).
 */
export function dataDirFromRoot(root: string): string | undefined {
  const m = /^(.*)[\\/]plugins[\\/]cache[\\/]([^\\/]+)[\\/]([^\\/]+)[\\/][^\\/]+[\\/]?$/.exec(root)
  if (m === null) return undefined
  const [, config = '', marketplace = '', plugin = ''] = m
  return joinPath(config, 'plugins', 'data', dataName(`${plugin}@${marketplace}`))
}

/**
 * The config directories the plugin's data may be under: CLAUDE_CONFIG_DIR when set (and then only
 * it), else `.claude` in the home directory (HOME, or USERPROFILE where Windows has no HOME; both
 * when they differ, as under Git Bash).
 */
export function configDirs(configDir: string | undefined, homes: readonly (string | undefined)[]): string[] {
  const configs = configDir ? [configDir] : homes.filter((h): h is string => !!h).map(h => joinPath(h, '.claude'))
  return [...new Set(configs.map(c => c.replace(/[\\/]+$/, '')))]
}

/**
 * Where the data directory of a plugin loaded with --plugin-dir may be: the engine keys it
 * `<name>@inline`, so `<config>/plugins/data/<name>-inline` under each of `configDirs`. Each a
 * candidate the shim may have written; the caller checks.
 */
export function inlineDataDirs(name: string, configDir: string | undefined, homes: readonly (string | undefined)[]): string[] {
  return configDirs(configDir, homes).map(c => joinPath(c, 'plugins', 'data', dataName(`${name}@inline`)))
}

/** A path compared as a path: either separator, no trailing one, a Windows drive path in any case. */
const pathKey = (p: string): string => {
  const k = p.replace(/\\/g, '/').replace(/\/+$/, '')
  return /^[A-Za-z]:\//.test(k) ? k.toLowerCase() : k
}
const isRecord = (v: unknown): v is Record<string, unknown> => v !== null && typeof v === 'object' && !Array.isArray(v)

/**
 * What the engine wrote about its plugins under one config directory, as read (the JSON text or
 * the parsed value; anything unreadable is undefined): `plugins/known_marketplaces.json` (each
 * marketplace's `installLocation` and `source.path`) and `plugins/installed_plugins.json` (each
 * `<plugin>@<marketplace>`'s `installPath`s).
 */
export type Registry = { config: string; known?: unknown; installed?: unknown }

const parsed = (v: unknown): unknown => {
  if (typeof v !== 'string') return v
  try {
    return JSON.parse(v)
  } catch {
    return undefined
  }
}

/**
 * The keys (`<name>@<marketplace>`) under which the engine loads the plugin whose folder is
 * `root`: a marketplace whose folder holds it (a directory marketplace's plugin is read in place:
 * `adage init`'s `adage@adage-local`, read from `$ADAGE_HOME/plugin/adage`), and an installed
 * entry whose `installPath` is it. Only the plugin's own name, in the order the files list them.
 */
export function registeredKeys(root: string, name: string, known: unknown, installed: unknown): string[] {
  const at = pathKey(root)
  const keys: string[] = []
  const k = parsed(known)
  if (isRecord(k)) {
    for (const [marketplace, entry] of Object.entries(k)) {
      if (!isRecord(entry)) continue
      const source = isRecord(entry.source) ? entry.source.path : undefined
      const homes = [entry.installLocation, source].filter((p): p is string => typeof p === 'string' && p !== '').map(pathKey)
      if (homes.some(h => at === h || at.startsWith(`${h}/`))) keys.push(`${name}@${marketplace}`)
    }
  }
  const i = parsed(installed)
  const plugins = isRecord(i) && isRecord(i.plugins) ? i.plugins : {}
  for (const [key, entries] of Object.entries(plugins)) {
    if (!key.startsWith(`${name}@`) || !Array.isArray(entries)) continue
    if (entries.some(e => isRecord(e) && typeof e.installPath === 'string' && pathKey(e.installPath) === at)) keys.push(key)
  }
  return [...new Set(keys)]
}

/**
 * Where the plugin's data directory may be when the engine's process does not carry
 * CLAUDE_PLUGIN_DATA (it hands it to command hooks only), in order: derived from an installed
 * plugin's root (and then only that); else, under each config directory, the data directory of
 * each key the engine registered the plugin's folder under (`registeredKeys`), then the
 * --plugin-dir layout's (`<name>-inline`). Each a candidate the shim may have written; the
 * caller checks. A key the folder is not registered under is never a candidate: its link may be
 * another install's.
 */
export function dataDirCandidates(root: string, name: string, registries: readonly Registry[]): string[] {
  const installed = dataDirFromRoot(root)
  if (installed !== undefined) return [installed]
  const out: string[] = []
  for (const r of registries) {
    const data = (key: string) => joinPath(r.config, 'plugins', 'data', dataName(key))
    out.push(...registeredKeys(root, name, r.known, r.installed).map(data), data(`${name}@inline`))
  }
  return [...new Set(out)]
}

/**
 * The suffix the session-start shim gives the entries it makes: on Windows it copies `hook.exe`
 * and `adage.exe` (a link would not run), elsewhere it links `hook` and `adage`. Windows is read
 * from the engine's environment (`OS=Windows_NT`, which Windows sets for every process).
 */
export const exeSuffix = (os: string | undefined): string => (os === 'Windows_NT' ? '.exe' : '')

/**
 * `<data>/bin/<BIN>`, the link the session-start shim made in the plugin's data directory
 * (binary.ts `dataDir`). There is no PATH fallback: when the shim linked `scripts/quiet` (no
 * binary could serve) the probe reads nothing and the mod stays inert, as the command hooks do.
 */
export function hookBinary(data: string | undefined, exe = ''): string | undefined {
  return data ? joinPath(data, 'bin', `${BIN}${exe}`) : undefined
}

/** `<data>/bin/adage`, which the shim links beside `bin/hook`: the verbs the mod draws from. */
export function cliBinary(data: string | undefined, exe = ''): string | undefined {
  return data ? joinPath(data, 'bin', `${CLI}${exe}`) : undefined
}

/**
 * The presence probe (`<bin> version`): a binary is there when it exits 0 and prints something.
 * `scripts/quiet` prints nothing, so with no binary the mod stays inert. Resolves the binary that
 * serves, or undefined.
 */
export async function probe(run: Run, bin: string | undefined): Promise<string | undefined> {
  if (bin === undefined) return undefined
  try {
    const ran = await run([bin, 'version'], { timeoutMs: 1000 })
    return ran.exitCode === 0 && ran.stdout.trim() !== '' ? bin : undefined
  } catch {
    return undefined // cannot start (no link yet), timed out, refused
  }
}

const parseObject = (text: string): HookAnswer | undefined => {
  const parsed: unknown = JSON.parse(text)
  if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) return undefined
  return parsed as HookAnswer
}

/**
 * Asks the binary about one event. `{ ok: true, answer: undefined }` is "nothing to do" (exit 0,
 * empty stdout); a JSON object is the answer; everything else is `{ ok: false }`.
 */
export async function ask(
  run: Run,
  bin: string | undefined,
  event: string,
  payload: { cwd?: string; [key: string]: unknown },
  timeoutMs: number,
): Promise<Asked> {
  if (bin === undefined) return { ok: false }
  try {
    const init: ProcessRunInit = { stdin: JSON.stringify(payload), timeoutMs }
    if (typeof payload.cwd === 'string' && payload.cwd !== '') init.cwd = payload.cwd
    const ran = await run([bin, 'hook', 'claude', event], init)
    if (ran.exitCode !== 0 || ran.isStdoutTruncated) return { ok: false }
    const text = ran.stdout.trim()
    if (text === '') return { ok: true, answer: undefined }
    const answer = parseObject(text)
    return answer === undefined ? { ok: false } : { ok: true, answer }
  } catch {
    return { ok: false }
  }
}

/** How long a read of `adage … --json` may take before the mod draws without it. */
const READ_TIMEOUT_MS = 10_000

/**
 * Reads one `adage … --json` object (the card, `graph`, `doctor`, `status`, `delegate status`),
 * in the session's directory. Anything but exit 0 with one JSON object is `{ ok: false }`, and the
 * drawing keeps what it had.
 */
export async function read(run: Run, cli: string | undefined, argv: readonly string[], cwd: string): Promise<Read> {
  if (cli === undefined) return { ok: false }
  try {
    const init: ProcessRunInit = { timeoutMs: READ_TIMEOUT_MS }
    if (cwd !== '') init.cwd = cwd
    const ran = await run([cli, ...argv], init)
    if (ran.exitCode !== 0 || ran.isStdoutTruncated) return { ok: false }
    const json = parseObject(ran.stdout.trim())
    return json === undefined ? { ok: false } : { ok: true, json }
  } catch {
    return { ok: false }
  }
}

/** Runs one allowed verb that prints a line for the person (`off`, `condition`): its stdout, or undefined. */
export async function say(run: Run, cli: string | undefined, argv: readonly string[], cwd: string): Promise<string | undefined> {
  if (cli === undefined) return undefined
  try {
    const init: ProcessRunInit = { timeoutMs: 120_000 }
    if (cwd !== '') init.cwd = cwd
    const ran = await run([cli, ...argv], init)
    return ran.exitCode === 0 ? ran.stdout.trim() : undefined
  } catch {
    return undefined
  }
}

/** How long `adage ledger note` may take: it merges under the ledger's lock, off every hook's path. */
export const NOTE_TIMEOUT_MS = 10_000

/**
 * Hands the session's usage to `adage ledger note` (plan A4, architecture §3.9) on stdin, in the
 * session's directory. True when the binary recorded it; a refusal (exit 2: a malformed note, or a
 * session the spool does not know) or any failure is false, and nothing else happens (fail open).
 */
export async function note(run: Run, cli: string | undefined, payload: unknown, cwd: string): Promise<boolean> {
  if (cli === undefined) return false
  try {
    const init: ProcessRunInit = { stdin: JSON.stringify(payload), timeoutMs: NOTE_TIMEOUT_MS }
    if (cwd !== '') init.cwd = cwd
    const ran = await run([cli, 'ledger', 'note'], init)
    return ran.exitCode === 0
  } catch {
    return false
  }
}

files.hooks/call.ts:
// The Bash call (docs/claude-mod/architecture.md §3.3, §3.4; plan C3, C6): before a Bash call runs,
// the binary is asked for its plan (`dry_run`), which names at most a receipt, a replacement for
// a known dead end, and a rewrite or advice. The person's rules are Claude Code's: each branch
// asks the engine what they decide (`$.tool.check`, which runs nothing) before the binary is asked
// for its final word (`verdict`), and only that word changes what happens to the call:
//
// - a fresh receipt answers the call in its place, only when the rules would have let the call as
//   written run unasked (no dialog appears for an answered call);
// - the replacement runs instead of the dead end, only when the rules treat both alike, whether
//   the dead end was learned or is a repository's declared instinct (the binary plans both alike; a
//   dead end piped into output filters is replaced as the whole new pipeline the binary plans, the
//   filters as written, and the rules are read on both whole pipelines);
// - a rewrite runs the call on the project's interpreter when the rules treat both alike; when
//   they do not, the binary turns it into advice, which the mod hands the model itself (the
//   command hook that follows for the same call prints nothing once a verdict decided it).
//
// Everything else, a failure included, runs the call as the model wrote it and leaves the command
// hook to decide as it always has (§6 invariants 1 and 2). `bashCall` is the call itself over
// plain deps; `onBashCall` binds it to the mod and keeps the markers each decision earns.
import type { ToolCallResult } from 'claude-code'

import { askBinary } from './binary'
import type { Asked } from './bridge'
import { keepCall } from './ledger'
import { mark } from './marks'
import type { AnswerAt, EventAt, Mod, NextAt } from './mod'
import { madeForAgentLine } from './predict'
import { answeredMark, receiptAnswerOf, receiptPlanOf, shortId } from './receipt'
import type { ReceiptAnswer, ReceiptPlan } from './receipt'
import { isRecord } from './shape'
import { substituteAnswerOf, substituteOf } from './substitute'
import type { Substitute } from './substitute'
import { markText, receiptOf, rewriteOf } from './view/lines'

/** What the mod tells the binary it found out (A1's `verdict`), exactly one decision per call. */
type Verdict = { engine: 'same' | 'differs'; substitute?: string } | { answered: 'receipt' }

/** The binary's `PreToolUse` payload for the mod's two phases (A1, C3, C6), exactly. */
export type PreToolPayload = {
  session_id: string
  cwd: string
  hook_event_name: 'PreToolUse'
  tool_name: 'Bash'
  tool_input: { command: string }
  tool_use_id: string
  /** Every payload the mod sends says so: the binary then reads the mod's capabilities (C9). */
  via: 'mod'
  /** The subagent the call is made in (`tool.call`'s `agentId`); absent on the main loop. */
  agent_id?: string
  dry_run?: true
  verdict?: Verdict
  /** Observe mode: the binary records what it would substitute, as the control arm does. */
  observe?: true
}

export type CallDeps = {
  /** False while the mod is inert: every call runs unread. */
  isActive: boolean
  /**
   * Observe mode (ADAGE_MOD_OBSERVE): the plan is asked for and a replacement's verdict with
   * `observe`, and nothing is replaced or answered.
   */
  isObserving: boolean
  ask: (payload: PreToolPayload) => Promise<Asked>
  context: () => Promise<{ sessionId: string; cwd: string }>
  /** The person's rules on a Bash command now (`$.tool.check`): `allow`, `ask` or `deny`. */
  check: (command: string) => Promise<string>
  /** One line under the call's permission dialog, if one opens (`$.ui.notice`). */
  notice: (toolUseId: string, text: string) => void
  /** Keeps a receipt that answered the call, for the card in its result row; a failure is ignored. */
  answered?: (toolUseId: string, answer: ReceiptAnswer) => Promise<void>
  /**
   * Keeps a covering receipt that did not answer the call (not fresh, the rules asked, or the
   * binary withheld it), for the dim line beside the run that happens (`result.receipt.beside`);
   * a failure is ignored.
   */
  beside?: (toolUseId: string, operation: string) => Promise<void>
  /** Keeps the replacement for the marker under the call's row (`tool.substituted`); a failure is ignored. */
  made?: (toolUseId: string, command: string) => Promise<void>
  /**
   * Keeps a rewrite for the marker under the call's row and says it under the dialog
   * (`tool.rewrite`); a failure is ignored.
   */
  rewrote?: (toolUseId: string, from: string, to: string) => Promise<void>
  /** Keeps what the final answer told the model beside the run (a receipt note); a failure is ignored. */
  delivered?: (toolUseId: string, context: readonly string[]) => Promise<void>
}

/** Both phases run before the call does, so each has the budget a command hook would. */
const PRE_TOOL_TIMEOUT_MS = 2000

/** The parts of a dry run's plan the mod acts on; a missing or malformed part is undefined. */
export type Plan = { receipt: ReceiptPlan | undefined; substitute: Substitute | undefined; rewrite: { command: string; kind: string } | undefined }

/**
 * The dry run's answer (`{ plan }`, docs/claude-mod/impl/wire.md), each part read by its own
 * reader; undefined when there is no plan at all. The plan's `advice` is not read: the command
 * hook that follows the call delivers it.
 */
export function planOf(answer: unknown): Plan | undefined {
  if (!isRecord(answer) || !isRecord(answer.plan)) return undefined
  const p = answer.plan
  return { receipt: receiptPlanOf(p.receipt), substitute: substituteOf(p.substitute), rewrite: rewritePlanOf(p.rewrite) }
}

/** The plan's `rewrite`: the command the call would run as, when U11 bound an environment here. */
export function rewritePlanOf(v: unknown): { command: string; kind: string } | undefined {
  if (!isRecord(v) || typeof v.command !== 'string' || v.command.trim() === '') return undefined
  return { command: v.command, kind: typeof v.kind === 'string' ? v.kind : '' }
}

/**
 * The final answer to an `engine` verdict, as the command hook's own output reads (A1): the
 * command the call runs as (`updatedInput.command`, a rewrite), what the model reads beside the
 * call (`additionalContext`: the rewrite's word, the advice, a receipt note) and the person's line
 * (`systemMessage`). Undefined when it says nothing the mod can use.
 */
export function verdictAnswerOf(answer: unknown): { command: string | undefined; context: string[] } | undefined {
  if (!isRecord(answer) || !isRecord(answer.hookSpecificOutput)) return undefined
  const out = answer.hookSpecificOutput
  const updated = isRecord(out.updatedInput) ? out.updatedInput.command : undefined
  const command = typeof updated === 'string' && updated.trim() !== '' ? updated : undefined
  const context = typeof out.additionalContext === 'string' && out.additionalContext !== '' ? [out.additionalContext] : []
  return command === undefined && context.length === 0 ? undefined : { command, context }
}

/** A result with more for the model to read after it; a refused call is returned as it was. */
function withContext(ran: ToolCallResult, context: readonly string[]): ToolCallResult {
  if (ran.deny !== undefined || context.length === 0) return ran
  return { ...ran, context: [...(ran.context ?? []), ...context] }
}

type BashCall = { command: string; tool_use_id: string; agentId?: string }

/**
 * The hook's body: `on('tool.call', { tool: 'Bash' }, ($, e, next) => bashCall(e, next, deps))`.
 * A call Adage made in the model's place (`adage_` id) is decided like any other, and its result
 * carries the line that says whose call it was (`madeForAgentLine`).
 */
export async function bashCall<E extends BashCall>(e: E, next: (e: E) => Promise<ToolCallResult>, deps: CallDeps): Promise<ToolCallResult> {
  const ran = await decided(e, next, deps)
  const line = deps.isActive ? madeForAgentLine(e.tool_use_id) : undefined
  return line === undefined ? ran : withContext(ran, [line])
}

/**
 * Any other tool's call (`on('tool.call', …)`, every tool but Bash, which `bashCall` answers): a
 * call Adage made in the model's place (the chain's reads, a skill) runs as it is, and its result
 * carries the line that says whose call it was; every other call passes untouched.
 */
export async function onPredictedCall(m: Mod, e: EventAt<'tool.call'>, next: NextAt<'tool.call'>): AnswerAt<'tool.call'> {
  // The ledger counts every main-loop call once: Bash's in its own hook, which a receipt may answer
  // before this one is reached.
  if (e.tool !== 'Bash') keepCall(m, e, next.origin)
  const line = e.tool === 'Bash' ? undefined : madeForAgentLine(e.tool_use_id)
  if (line === undefined) return next(e)
  const ran = await next(e)
  return ran.deny !== undefined ? ran : { ...ran, context: [...(ran.context ?? []), line] }
}

async function decided<E extends BashCall>(e: E, next: (e: E) => Promise<ToolCallResult>, deps: CallDeps): Promise<ToolCallResult> {
  if (!deps.isActive || typeof e.command !== 'string') return next(e)
  let ctx: { sessionId: string; cwd: string }
  try {
    ctx = await deps.context()
  } catch {
    return next(e)
  }
  const id = e.tool_use_id
  const base: PreToolPayload = {
    session_id: ctx.sessionId,
    cwd: ctx.cwd,
    hook_event_name: 'PreToolUse',
    tool_name: 'Bash',
    tool_input: { command: e.command },
    tool_use_id: id,
    via: 'mod',
    ...(typeof e.agentId === 'string' && e.agentId !== '' ? { agent_id: e.agentId } : {}),
    ...(deps.isObserving ? { observe: true as const } : {}),
  }
  const ask = (p: PreToolPayload) => deps.ask(p).catch((): Asked => ({ ok: false }))
  const quiet = (work: Promise<void> | undefined) => (work ?? Promise.resolve()).catch(() => undefined)

  const planned = await ask({ ...base, dry_run: true })
  const plan = planned.ok ? planOf(planned.answer) : undefined
  if (plan === undefined) return next(e)

  // The rules on the call as written, asked at most once whichever branches need it; a check that
  // fails is no answer, and no branch that needs it is taken.
  let written: Promise<string | undefined> | undefined
  const asWritten = () => (written ??= deps.check(e.command).then(d => d, () => undefined))
  const alike = async (other: string): Promise<boolean | undefined> => {
    const [a, b] = await Promise.all([asWritten(), deps.check(other).then(d => d, () => undefined)])
    return a === undefined || b === undefined ? undefined : a === b
  }

  // §3.3 The receipt as the result: no dialog appears for an answered call, so only a call the
  // rules would have let run unasked is answered. A receipt that is not fresh, or a call the rules
  // ask about, runs: the binary says nothing more than it would have.
  const receipt = plan.receipt
  if (receipt?.fresh === true && receipt.result !== '' && !deps.isObserving && (await asWritten()) === 'allow') {
    const final = await ask({ ...base, verdict: { answered: 'receipt' } })
    const answer = final.ok ? receiptAnswerOf(final.answer) : undefined
    if (answer !== undefined) {
      await quiet(deps.answered?.(id, answer))
      return { result: { stdout: answer.result, stderr: '', interrupted: false }, ...(answer.note === '' ? {} : { context: [answer.note] }) }
    }
  }
  // A covering receipt that did not answer the call: the run happens, and the row says a receipt
  // covers it (T-C3-07). The command hook still delivers a fresh one's note beside the result.
  if (receipt !== undefined && receipt.operation !== '' && !deps.isObserving) await quiet(deps.beside?.(id, receipt.operation))

  // §3.4 The dead end that never runs: the planned command (learned, or a declared instinct's),
  // only on the same verdict for the call and for the command the binary planned (the whole
  // pipeline, when the dead end heads one).
  const sub = plan.substitute
  if (sub !== undefined && (await alike(sub.command)) === true) {
    const final = await ask({ ...base, verdict: { engine: 'same', substitute: sub.route } })
    const made = final.ok ? substituteAnswerOf(final.answer) : undefined
    if (made !== undefined && !deps.isObserving) {
      await quiet(deps.made?.(id, made.command))
      try {
        deps.notice(id, made.context)
      } catch {
        // No dialog is open for the call: the model's line below still says it.
      }
      return withContext(await next({ ...e, command: made.command }), [made.context])
    }
    // Withheld (the control arm, or observe mode): the binary records `would_substitute` and leaves
    // the call undecided, so the interpreter rewrite below still decides it: the verdict here in
    // the control arm (recorded withheld there), the command hook in observe mode.
  }

  // §3.4 Rewrites checked by the engine: the engine's comparison replaces the planner's own reading
  // of the settings files. Advice alone, or nothing, is the command hook's to deliver as before.
  const rewrite = plan.rewrite
  if (rewrite === undefined || deps.isObserving) return next(e)
  const same = await alike(rewrite.command)
  if (same === undefined) return next(e)
  const final = await ask({ ...base, verdict: { engine: same ? 'same' : 'differs' } })
  const said = final.ok ? verdictAnswerOf(final.answer) : undefined
  if (said === undefined) return next(e)
  await quiet(deps.delivered?.(id, said.context))
  if (said.command === undefined || said.command === e.command) return withContext(await next(e), said.context)
  await quiet(deps.rewrote?.(id, e.command, said.command))
  return withContext(await next({ ...e, command: said.command }), said.context)
}

/** The rewrite under a call's row (`tool.rewrite`), and the same line under its dialog. */
async function rewrote(m: Mod, id: string, from: string, to: string): Promise<void> {
  const rw = rewriteOf(from, to)
  if (rw === undefined) return
  const x = { id, kind: 'rewrite' as const, ...rw }
  await mark(m, x)
  try {
    m.ui.notice(id, markText(x, (await m.state.mode.read()).ascii))
  } catch {
    // No dialog is open for the call: the row's marker says it.
  }
}

/**
 * The hook body (`on('tool.call', { tool: 'Bash' }, …)`, §3.3, §3.4; C3, C6): a fresh receipt
 * answers the call when the rules would have let it run unasked; a dead end's replacement or a rewrite
 * runs only on the same verdict for both commands. Each decision keeps its marker for the row.
 */
export async function onBashCall(m: Mod, e: EventAt<'tool.call', { tool: 'Bash' }>, next: NextAt<'tool.call', { tool: 'Bash' }>): AnswerAt<'tool.call', { tool: 'Bash' }> {
  keepCall(m, e, next.origin)
  return bashCall(e, next, {
    isActive: m.rt.bin !== undefined,
    isObserving: m.rt.observing,
    ask: payload => askBinary(m, 'PreToolUse', payload, PRE_TOOL_TIMEOUT_MS),
    context: async () => ({ sessionId: await m.session.id(), cwd: await m.session.cwd() }),
    check: command => m.checkBash(command),
    notice: (id, text) => m.ui.notice(id, text),
    answered: async (id, a) => {
      const x = answeredMark(id, a)
      if (x !== undefined) await mark(m, x)
    },
    beside: (id, operation) => mark(m, { id, kind: 'receipt', receipt: shortId(operation) }),
    made: (id, command) => mark(m, { id, kind: 'substituted', command }),
    rewrote: (id, from, to) => rewrote(m, id, from, to),
    delivered: async (id, context) => {
      const rc = receiptOf(context)
      if (rc !== undefined) await mark(m, { id, kind: 'receipt', receipt: rc })
    },
  })
}

